import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { CheckBox } from '@cetus/ui-kit'
import Icon from '@cetus/ui-kit/src/components/Icon'
import { Button, HStack, Image, Menu, MenuButton, MenuList, Text } from '@chakra-ui/react'
import { SwitchChainProps } from './type'

function SwitchChain({ chainsList, currentChain, onChange }: SwitchChainProps) {
  const { isApp } = useWindowWidth()
  return (
    <Menu>
      {({ isOpen }) => (
        <>
          <MenuButton
            as={Button}
            variant="outline"
            h="36px"
            borderRadius="8px"
            p={isApp ? '6px' : '6px 11px'}
            _hover={{
              bg: 'menu_item_hover_bg'
            }}
            rightIcon={
              <Icon
                xlinkHref="#icon-icon_arrow"
                transform={isOpen ? 'rotate(180deg)' : 'rotate(0deg)'}
                transition="transform 0.5s"
                fontSize="12px"
                variant="gray"
              />
            }
          >
            <HStack>
              <Image src={currentChain.icon} w="20px" h="20px" borderRadius="50%" />
              {!isApp && (
                <Text fontSize="14px" color="text_caption" fontWeight="500">
                  {currentChain.name}
                </Text>
              )}
            </HStack>
          </MenuButton>
          <MenuList display="flex" flexDirection="column" gap="16px">
            <Text h="20px" lineHeight="20px" fontSize="16px" color="text_caption" fontWeight="500">
              Switch Chain
            </Text>
            {chainsList.map(chain => (
              <HStack
                key={chain.name}
                w="100%"
                onClick={() => onChange(chain)}
                p="8px 16px"
                justify="space-between"
                border="1px solid"
                borderColor="transparent"
                h="42px"
                _hover={{
                  bg: 'menu_item_bg',
                  borderColor: 'border',
                  borderRadius: '12px'
                }}
              >
                <HStack>
                  <Image src={chain.icon} w="24px" h="24px" borderRadius="50%" />
                  <Text fontSize="14px" color="text_caption">
                    {chain.name}
                  </Text>
                </HStack>
                <CheckBox checked={currentChain.name === chain.name} onClick={() => {}} />
              </HStack>
            ))}
          </MenuList>
        </>
      )}
    </Menu>
  )
}

export default SwitchChain
